VStack(alignment: .leading, spacing: 0) {
    MonarchDivider()
    DisclosureGroup({{items.0.title}}, isExpanded: Binding(get: { open == {{items.0.id}} }, set: { open = $0 ? {{items.0.id}} : nil })) {
        Text({{items.0.body}}).monarchTextStyle(.body)
    }
    .accessibilityAddTraits(.isHeader)
    MonarchDivider()
    DisclosureGroup({{items.1.title}}, isExpanded: Binding(get: { open == {{items.1.id}} }, set: { open = $0 ? {{items.1.id}} : nil })) {
        Text({{items.1.body}}).monarchTextStyle(.body)
    }
    .accessibilityAddTraits(.isHeader)
    MonarchDivider()
}
.disclosureGroupStyle(.monarch)

examples.code:
VStack(alignment: .leading, spacing: 0) {
    MonarchDivider()
    DisclosureGroup("When am I billed?", isExpanded: Binding(get: { open == "billing" }, set: { open = $0 ? "billing" : nil })) {
        Text("On the first of each month, for the seats in use.").monarchTextStyle(.body)
    }
    .accessibilityAddTraits(.isHeader)
    MonarchDivider()
    DisclosureGroup("Can I cancel at any time?", isExpanded: Binding(get: { open == "cancel" }, set: { open = $0 ? "cancel" : nil })) {
        Text("Yes. Access continues to the end of the paid period.").monarchTextStyle(.body)
    }
    .accessibilityAddTraits(.isHeader)
    MonarchDivider()
}
.disclosureGroupStyle(.monarch)

VStack(alignment: .leading, spacing: 0) {
    ForEach(["Shipping", "Returns", "Warranty"], id: \.self) { title in
        DisclosureGroup(title, isExpanded: Binding(
            get: { openSections.contains(title) },
            set: { isOpen in
                if isOpen { openSections.insert(title) } else { openSections.remove(title) }
            }
        )) {
            Text("Details about \(title.lowercased()).").monarchTextStyle(.body)
        }
        MonarchDivider()
    }
}
.disclosureGroupStyle(.monarch)
